judgement.code:
// (the gist is AI-written: the AI label under the CP badge says so; the open row shows the rules as written instead)
const aiLabel = '<span class="tg m ai" title="Summary written by AI: tap for the rules as written">AI</span>';

const stratHead = s => { const pb = perBattle(s);
  return '<span class="cpw"><span class="cp' + (s.cp >= 2 ? ' hot' : '') + '">' + esc(s.cp) + '<small>CP</small></span>' + (s.gist ? aiLabel : '') + '</span><span class="sh"><b>' + esc(s.name) + '</b>' +
  (s.gist ? '<span class="sg">' + esc(s.gist) + '</span>' : '') + '<span class="sw"><em>' + esc([stratWhenShort(s), s.limit, s.cpNote].filter(Boolean).join(' · ')) + '</em> ' + esc(usersLine(s)) + '</span>' +
  (pb ? ticks('s:' + s.id, pb.n, '', s.name) : '') + '</span>'; };

.strat > summary .cp{margin-top:2px}
.cpw{position:relative; display:block}
.cpw .ai{position:absolute; top:100%; left:0; right:0; margin-top:4px; text-align:center; font-size:10.5px; line-height:1}   /* (under the badge, out of the flow: nothing on the row moves) */
.strat[open] .cpw .ai{display:none}
.sh span.sw em{font-style:normal; font-weight:600; color:var(--fg2); margin-right:3px}
.sh .ticks{margin-top:4px}
.sh span.sg{font-size:13.5px; line-height:1.32; color:var(--fg2); margin:1px 0}
.rules .dsec{margin-top:22px}
.rules h2.lbl, .rules h3.who{margin-bottom:0}
.rules h2.lbl{margin-top:0}
.ab.rr > summary .an{flex-direction:column; align-items:flex-start; gap:1px}
.ab.rr .rs{font-size:12.5px; color:var(--muted)} .ab.rr .rs .tg{font-size:12.5px}
.ab.rr.na > summary b{color:var(--muted)}
.rules .dline.rs .none .link{color:var(--muted)}
.rules .who{margin-top:14px}
.rules .dline.rs{font-size:13.5px}
.rules .dline.rs > .il{font:600 11px/1.2 var(--f-head); letter-spacing:.1em; color:var(--muted); margin-right:6px}
.gvl{font-style:normal; position:relative} .gvl::after{content:'+'; position:absolute; top:-3px; right:-7px; font:700 9px/1 var(--f-head); color:var(--accent)}
.dline.sl p{margin:3px 0 0} .dline.sl .sln{font:600 11.5px/1.2 var(--f-head); letter-spacing:.08em; text-transform:uppercase; color:var(--muted); margin-right:4px}
.abl .xp{border-bottom:1px solid var(--line)}
.urs{border-top:1px solid var(--line)}
.urr{padding:6px 2px 7px; border-bottom:1px solid var(--line)}
.urn .link{font:700 16px/1.2 var(--f-head); letter-spacing:.02em}
.uru{margin:2px 0 0 12px; font-size:14px; line-height:1.45}
.urq{display:block; margin-top:1px; font-size:13px; line-height:1.4; color:var(--muted)}
.urq ul{margin:1px 0 2px; padding-left:18px} .urq li{margin:1px 0}
.urq .link{color:var(--fg2)}
.uru .from{color:var(--muted)}
.gsrc{margin:6px 0 10px; padding:8px 10px; border-left:3px solid var(--accent); background:var(--surface); border-radius:0 8px 8px 0}
.gh{margin:0 0 4px} .gh .tg{margin-left:4px}
.gw2{margin:0 0 4px; font-size:12.5px; color:var(--muted)}
.gown{margin-top:16px; padding-top:10px; border-top:1px solid var(--line); color:var(--fg2)}
.gown, .gown .rt, .gown p, .gown li{font-size:13px; line-height:1.4}
.wr i.hi{font-style:normal; display:inline-block; min-width:26px; padding:1px 4px; border-radius:5px; background:var(--accent); color:var(--accent-ink)}
.wr i.hb{display:block; font:700 12px/1.1 var(--f-head); font-style:normal; color:var(--accent)}
.wr i.alt{font-style:normal; color:var(--accent)}
.varc{padding-top:1px; font-size:12.5px; line-height:1.35; color:var(--muted)}
.varc b{color:var(--accent); font:700 13.5px var(--f-head)}
.mods{margin-top:6px; display:grid; gap:4px}
.mods.all{margin:10px 0 2px}
.mods.all > .il{margin:0 0 1px}
.mod{border-left:2px solid var(--accent); padding:1px 0 1px 8px; font-size:13px; line-height:1.35}
.mod .from{color:var(--muted)}
/* whose weapons these are (leader vs bodyguard): a chip, not a whisper */
.who{display:inline-block; justify-self:start; margin:12px 0 4px; padding:4px 8px 3px; border-radius:4px; border:1px solid var(--line); background:var(--surface2); font:700 14px/1 var(--f-head); letter-spacing:.08em; text-transform:uppercase; color:var(--fg)}
/* phones under 360px: narrower columns (after the rules it overrides) */
@media (max-width:359px){
  .ranged .wr, .wh.ranged, .both .wr, .wh.both{grid-template-columns:minmax(0,1fr) 28px 38px 24px 22px 26px 30px}
  .melee .wr, .wh.melee{grid-template-columns:minmax(0,1fr) 38px 24px 22px 26px 30px}
  .wr.p > span.n{padding-left:2px}
  .ar{margin-right:1px; font-size:10px}
  .wr > span.n, .st > span.n{overflow-wrap:anywhere}
  .st > span.n{font-size:13px; padding-left:6px}
  .x{margin-left:6px; font-size:13px}
}
/* ---------- the datasheet as New Recruit draws it: one framed sheet of table sections ----------
   a slate band (points, name), grey header rows that carry the column labels, hairline rows,
   whose a row is after its name in grey ("- Mek"), and the keywords at the bottom as pills */
/* heading levels: the unit (its band) > a section box (Ranged Weapons, Melee Weapons, Abilities: its own box, a gap
   above, an angled darker band) > a table header (Models, Unit: grey row) > a part of the unit (Mek, Tankbustas, Whole unit) */
.ds{margin-top:8px}
.dbx{--ch:7px; border:1px solid var(--line); border-top:0; border-radius:0 0 3px 3px;
  clip-path:polygon(var(--ch) 0, calc(100% - var(--ch)) 0, 100% var(--ch), 100% 100%, 0 100%, 0 var(--ch))}   /* the side lines start where the angled corner meets them */
.ds > .dbx:first-child{--ch:9px}
.dbx.dft{clip-path:none}
.ds .dbx + .dbx{margin-top:14px}
.dbx.dft{border-top:1px solid var(--line); border-radius:3px}
.dh2, .ds .dbx > .wh.both, .ds .dbx > .ab.pf > summary{margin:0 -1px; background:var(--ds-h2); clip-path:polygon(7px 0, calc(100% - 7px) 0, 100% 7px, 100% 100%, 0 100%, 0 7px)}
.dh2{display:flex; flex-wrap:wrap; justify-content:space-between; align-items:baseline; gap:2px 8px; padding:8px 11px 6px}
.ds .dbx > .wh.both{padding:8px 11px 6px}
.dh2 > span:first-child, .ds .dbx > .wh.both .n, .ds .dbx > .ab.pf > summary b.kh{font:700 14.5px/1.15 var(--f-head); letter-spacing:.07em; text-transform:uppercase; color:var(--ds-h2-fg)}
.ds .dbx > .wh.both > span:not(.n){color:var(--ds-h2-col)}
.dh2 + .mods, .dh2 + .abl{border-top:0}
.ds .dbx > .ab.pf{border-top:0}
.dsh{display:flex; flex-wrap:wrap; align-items:baseline; justify-content:space-between; gap:2px 12px; margin:0 -1px; padding:7px 12px 6px;
  background:var(--ds-band); color:var(--ds-band-fg); clip-path:polygon(9px 0, calc(100% - 9px) 0, 100% 9px, 100% 100%, 0 100%, 0 9px)}
.dpts{font:700 15px/1.15 var(--f-head); letter-spacing:.06em; text-transform:uppercase; white-space:nowrap}
.dsn{flex:1 1 auto; min-width:0; text-align:left; font:700 15px/1.15 var(--f-head); letter-spacing:.08em; text-transform:uppercase}
.dpts{margin-left:auto}
.dsm{display:flex; flex-wrap:wrap; align-items:baseline; gap:2px 10px; padding:5px 10px; font-size:12.5px; line-height:1.35; color:var(--muted)}
.dhd, .ds .st > span.h, .ds .wh.both > span, .ds .wh.both .n, .dk{font:500 12.5px/1.2 var(--f-body); letter-spacing:0; text-transform:none; color:var(--ds-head-fg)}
.dhd{display:flex; flex-wrap:wrap; justify-content:space-between; align-items:baseline; gap:2px 8px; padding:5px 10px 4px; background:var(--ds-head)}
.dhd .lbn{margin:0; font:inherit; font-size:12px}
.ds .mdl .dhd, .ds .ml{display:grid; grid-template-columns:minmax(0,1.15fr) minmax(0,1fr); gap:0 10px}
.ds .ml{padding:5px 10px; border-top:1px solid var(--line); font-size:13.5px; line-height:1.3}
.ds .dhd + .ml{border-top:0}
.ds .mn{font-weight:600}
.ds .mg{display:block; font-size:13px; color:var(--fg2)}
.ds .mlt{display:block; margin:1px 0 0; font-size:13px}
.ds .mlt::before{content:'• '; color:var(--muted)}
.ds .st{border-radius:0; background:none}
.ds .st > span{display:flex; align-items:center; justify-content:center; padding:5px 0; font:700 17px/1 var(--f-head); border-top:1px solid var(--line)}
.ds .st > span.h{padding:5px 0 4px; border-top:0; background:var(--ds-head)}
.ds .st > span.h.n{justify-content:flex-start; padding-left:10px}
.ds .st > span.n{flex-direction:column; align-items:flex-start; gap:1px; padding:4px 4px 4px 10px}
.ds .st > span.n b{font:600 14.5px/1.15 var(--f-head); letter-spacing:.01em}
.ds .st > span.n .x{margin-left:6px; font-size:13px}
.ds .st > span.n small{font:500 11.5px/1.1 var(--f-body); color:var(--muted)}
.dnt{padding:0 10px 7px; border-top:1px solid var(--line)}
.dnt:empty{display:none}
.dnt > :first-child{margin-top:6px}
.ds .wh.both{padding:5px 10px 4px; background:var(--ds-head); box-shadow:none}
.ds .wh.both .n{white-space:nowrap}
.ds .wb, .ds .wb:has(> .wr .x){padding:5px 10px 4px}
.ds .who{display:block; justify-self:stretch; margin:0; padding:5px 10px 3px; border:0; border-top:1px solid var(--line); border-radius:0; background:var(--surface); font:600 12.5px/1.2 var(--f-head); letter-spacing:.08em; color:var(--fg2)}
.ds .who + .wb{border-top:0}
.ds .wj{margin:1px 10px}
.ds .use{padding:4px 10px 3px}
.ds .mods{margin:0; padding:7px 10px 8px; border-top:1px solid var(--line)}
.ds .mods.all{margin:0}
.ds .msep{margin:4px 0 1px}
.ds .mod{font-size:12.5px} .ds .mod b{font-weight:600}
.ds .ab.pf{border-bottom:0; border-top:1px solid var(--line)}
.ds .ab.pf > summary{padding:4px 10px; background:var(--ds-head)}
.ds .ab.pf > summary b.kh{font:500 12.5px/1.2 var(--f-body); letter-spacing:0; text-transform:none; color:var(--ds-head-fg)}
.ds .ab.pf .wh.both{background:none; padding-top:4px}
.ds .abl{border-top:0}
.ds .ab > summary{padding:4px 10px; min-height:38px}
.ds .ab > .body{padding:0 10px 10px}
.ds .abl .ab:last-child{border-bottom:0}
.awho{font-size:13px; color:var(--muted)}
.ds .an .awho{margin-left:-3px}
.dft{border-top:1px solid var(--line)}
.dkv{display:grid; grid-template-columns:86px minmax(0,1fr)}
.dkv + .dkv{border-top:1px solid var(--line)}
.dk{padding:7px 6px 6px 10px; background:var(--ds-head)}
.dv{min-width:0; padding:5px 10px 6px; font-size:14px; line-height:1.5}
.dv p{margin:0} .dv p + p{margin-top:2px}
.dv .sln{font:600 11.5px/1.2 var(--f-head); letter-spacing:.08em; text-transform:uppercase; color:var(--muted); margin-right:4px}
.dv .link{white-space:nowrap}
/* (on the narrowest phones a rule name longer than the line, "Instruments of the Emperor’s Wrath" at 320px, wraps instead of
   widening the page) */
@media (max-width:359px){ .dv .link{white-space:normal} }
.pills{display:flex; flex-wrap:wrap; gap:5px; padding:2px 0}
.pill{display:inline-block; padding:4px 9px 3px; border-radius:999px; background:var(--surface2); box-shadow:inset 0 0 0 1px var(--pill-line); font:600 12px/1.2 var(--f-head); letter-spacing:.06em; text-transform:uppercase; color:var(--fg2)}
.kwn{display:block; margin-top:4px; font-size:12px; line-height:1.35; color:var(--muted)}
@media (max-width:359px){
  .ds .st > span{font-size:16px}
  .ds .st > span.h{font-size:11px}
  .ds .st > span.n{padding-left:8px}
  .dhd, .ds .wh.both, .ds .wb, .ds .wb:has(> .wr .x), .ds .ml, .ds .ab > summary, .ds .ab > .body, .dsm, .ds .mods, .ds .who, .dnt, .dv{padding-left:8px; padding-right:8px}
  .ds .wh.both > span{font-size:11px}
  .dkv{grid-template-columns:74px minmax(0,1fr)}
  .ds .ml{grid-template-columns:minmax(0,1fr)}
  .ds .mdl .dhd{display:flex}
  .ds .wh.both .n{font-size:12px}
  .ds .dbx > .wh.both .n{font-size:13px; white-space:normal}
  .ds .dbx > .wh.both, .dh2{padding-left:9px; padding-right:9px}
  .dk{padding-left:8px}
}
/* every band (the unit's, a section's, a role's on the Units list) is lit from its top edge in the accent */
.ds .dsh, .dh2, .ds .dbx > .wh.both, .ds .dbx > .ab.pf > summary, .rgh{background-image:var(--ds-edge)}
/* slice screens: one band per unit, pinned until the next unit's band pushes it off */
.us{padding-bottom:4px}
.band{position:sticky; top:var(--top); z-index:4; display:flex; align-items:baseline; gap:8px; width:100%; min-height:40px; margin-top:12px; padding:9px 10px 8px;
  background:var(--surface2); text-align:left; border-radius:6px}
.band b{font:700 16.5px/1.15 var(--f-head); letter-spacing:.02em}
.band{flex-wrap:nowrap; row-gap:2px}
.band b{min-width:0}
.band .tgs{flex:1 1 auto; min-width:0; display:flex; flex-wrap:wrap; gap:0 8px}
.band .tgs .tg{white-space:normal}
.band .go{align-self:center; color:var(--accent); flex:none; margin-left:auto}
.slice > .us:first-child .band{margin-top:4px}
.band + .wt, .band + .al{margin-top:4px}
.subbar .wh{padding-bottom:0}
/* abilities */
.al > div{padding:7px 0; border-top:1px solid var(--line)}
.al > div:first-child{border-top:0; padding-top:2px}
.al .ah{display:flex; flex-wrap:wrap; align-items:baseline; gap:1px 8px; margin-bottom:2px}
.al .ah b{font:700 16px/1.2 var(--f-head); letter-spacing:.02em}
.al .rt{font-size:14.5px; line-height:1.4}
.kwline{font-size:14px; line-height:1.5; color:var(--muted)}

/* ---------- stratagems ---------- */
.tools{display:flex; justify-content:flex-end; margin:2px 0 -8px}
.qh{margin:10px 0 3px; font:700 12px/1.2 var(--f-head); letter-spacing:.09em; text-transform:uppercase; color:var(--fg)}
.qh:first-child{margin-top:2px}
.qol{margin:0; padding-left:20px}
.qtab{display:grid; grid-template-columns:auto 1fr; gap:2px 14px; font-variant-numeric:tabular-nums}
.qtab span:nth-child(odd){font:700 15px/1.35 var(--f-head); color:var(--accent)}
.row .c.on{color:var(--accent)}
.verif{display:flex; align-items:center; gap:10px; width:100%; margin-top:14px; padding:10px 10px; border-radius:6px; background:var(--surface); text-align:left; font-size:13.5px; line-height:1.35; color:var(--fg2)}
.verif .ic{width:22px; height:22px; color:var(--ok); flex:none}
.verif b{color:var(--fg); font-weight:600}
.verif > span{flex:1; min-width:0; white-space:normal}
.vchk{margin:3px 0; font-size:14px; line-height:1.45}
.vchk b{font-weight:600}
/* How the app works: the steps, the tables' map, a card per table (one real row, every column tagged by where it comes from) */
.hwrow{margin-top:18px}
.hwi, .hwp{font-size:14.5px; line-height:1.5; color:var(--fg2); margin-top:10px}
.hwflow{list-style:none; margin:12px 0 0; padding:0; display:grid; gap:14px}
.hwflow li{position:relative; display:grid; gap:2px; padding:8px 10px; border:1px solid var(--line); border-radius:6px; background:var(--surface); font-size:14px; line-height:1.4; color:var(--fg2)}
.hwflow li + li::before{content:""; position:absolute; left:18px; top:-15px; height:14px; border-left:2px solid var(--muted)}
.hwflow b{font:700 16px/1.15 var(--f-head); letter-spacing:.02em; color:var(--fg)}
.hwflow .link{padding-bottom:0}
.hwmap{margin:6px 0 0; padding:6px 4px; border:1px solid var(--line); border-radius:6px; background:var(--surface)}
.hwmap svg{display:block; width:100%; height:auto}
.hwmap rect{fill:var(--bg); stroke:var(--line); stroke-width:1.2}
.hwmap .t{font:700 12.5px var(--f-head); letter-spacing:.03em; fill:var(--fg)}
.hwmap .s{font:400 11px var(--f-body); letter-spacing:0; fill:var(--muted)}
.hwmap .k{font:600 10.5px var(--f-body); fill:var(--accent)}
.hwmap .ar{fill:none; stroke:var(--muted); stroke-width:1.4}
.hwmap marker path{fill:var(--muted)}
.hwleg{margin-top:8px}
.ly{display:inline-block; font:700 10.5px/1 var(--f-head); letter-spacing:.06em; text-transform:uppercase; border-radius:4px; padding:3px 5px 2px; white-space:nowrap; vertical-align:1px; color:var(--muted); box-shadow:inset 0 0 0 1px var(--line)}
.ly.sum{color:var(--accent-ink); background:var(--accent); box-shadow:none}
.ly.read{color:var(--accent); box-shadow:inset 0 0 0 1.5px var(--accent)}
.ly.hand{color:var(--fg); background:var(--surface2); box-shadow:none}
.xp.hwc{margin-top:6px; padding:0 10px; border:1px solid var(--line); border-radius:6px; background:var(--surface); scroll-margin-top:calc(var(--top) + 8px); min-width:0}
.xp.hwc > summary{padding:5px 0; min-height:0}
.xp.hwc > summary b{letter-spacing:.04em; overflow-wrap:anywhere}
.xp.hwc > summary .xh > span{font-size:13px; line-height:1.35}
.hwcnt{font:600 13.5px var(--f-head); color:var(--fg2); font-variant-numeric:tabular-nums}
.xp.hwc > .body{padding:0 0 4px}
.hwidx{margin-top:8px}
#sec-hw-trust{scroll-margin-top:calc(var(--top) + 8px)}
.hww{font-size:13.5px; line-height:1.4; color:var(--fg2); margin-top:2px}
.hwk{font-size:13.5px; line-height:1.5; margin-top:4px; overflow-wrap:anywhere}
.hwk .link{padding-bottom:0}
.hwe{margin-top:10px}
.hwx{margin-top:4px}
.hwx .pgr{grid-template-columns:minmax(72px, 28%) minmax(0,1fr); padding:5px 0 4px}
.hwx .pgk{padding-top:0; text-transform:none; letter-spacing:.02em; font-size:13.5px; color:var(--fg); overflow-wrap:anywhere}
.hwx .pgv{display:flex; align-items:baseline; gap:4px 8px; font-size:13.5px; line-height:1.4}
.hwx .pgv > span:first-child{flex:1; min-width:0; overflow-wrap:anywhere}
.hwx .pgv > .ly{flex:none}
.hws{color:var(--muted)}
.hwc .xp{margin:8px -10px 0; padding:0 10px; border-bottom:0; border-top:1px solid var(--line)}
.hwc .xp > .body{padding-bottom:8px}
.hwl{font-size:13px; line-height:1.6; margin:5px 0 0; color:var(--fg2); overflow-wrap:anywhere}
.hwct > b{font:700 15px var(--f-head); letter-spacing:.03em; overflow-wrap:anywhere}
.hwct .hwn{font:600 13px var(--f-head); color:var(--muted)}
.hwct + .hwct{margin-top:10px; padding-top:8px; border-top:1px solid var(--line)}
/* home: filters, random army */
.hfs{display:flex; flex-wrap:wrap; gap:6px; margin:12px 0 2px}
.hfc{display:inline-flex; align-items:center; gap:3px; min-height:36px; max-width:100%; padding:0 6px 0 11px; border-radius:18px; box-shadow:inset 0 0 0 1px var(--line); background:var(--surface);
  font:700 13.5px/1 var(--f-head); letter-spacing:.06em; text-transform:uppercase; color:var(--fg2)}
.hfc span{white-space:nowrap; overflow:hidden; text-overflow:ellipsis; min-width:0}
.hfc.on{background:var(--accent); color:var(--accent-ink); box-shadow:none}
.hfc.on .chev{color:inherit}
.hfc:active{opacity:.75}
.hfx{min-height:36px; padding:0 8px; font:700 13.5px/1 var(--f-head); letter-spacing:.06em; text-transform:uppercase; color:var(--accent)}
.hlh{display:flex; align-items:center; justify-content:space-between; gap:10px; margin:12px 0 4px}
.hlh .grp-h{margin:0}
.hfn{margin-left:6px; color:var(--muted); letter-spacing:.06em}
.rnd{display:inline-flex; align-items:center; gap:6px; min-height:36px; margin:0 -4px 0 0; padding:0 6px; font:700 13.5px/1 var(--f-head); letter-spacing:.06em; text-transform:uppercase; color:var(--accent)}
.rnd .ic{width:18px; height:18px}
.rnd:active{opacity:.6}
/* a list's row with its star (Favorites): the row and the star are two buttons side by side */
.arw{display:flex; align-items:stretch; border-bottom:1px solid var(--line)}
.arw > .row{flex:1; min-width:0; border-bottom:0}
.fav{flex:none; width:44px; display:grid; place-items:center; margin-right:-10px; color:var(--muted)}
.fav svg{width:22px; height:22px}
.fav.on, .icon-btn.fav.on{color:var(--accent); --star-fill:currentColor}
.fav:active{opacity:.6}
.icon-btn.fav{width:44px; color:var(--fg)}
.hll{display:flex; align-items:center; min-width:0}
.srt{display:inline-flex; align-items:center; gap:3px; min-height:36px; margin-left:-2px; padding:0 2px}
.srt .chev{color:var(--muted)}
.srt:active{opacity:.6}
.hfl .row{padding-right:4px}
.hfl .row[disabled]{opacity:.4}
.hfl .row .ic{width:20px; height:20px}
.hfl .row .ok{color:var(--accent)}
.hfl .row.on b{color:var(--accent)}
.reel{position:relative; height:192px; margin:14px 0 4px; overflow:hidden; border-radius:8px; background:var(--surface);
  -webkit-mask-image:linear-gradient(transparent, #000 30%, #000 70%, transparent); mask-image:linear-gradient(transparent, #000 30%, #000 70%, transparent)}
.reel::after{content:""; position:absolute; left:0; right:0; top:64px; height:64px; box-shadow:inset 0 1px 0 var(--accent), inset 0 -1px 0 var(--accent); pointer-events:none; transition:background .3s}
.reel.hit::after{background:color-mix(in srgb, var(--accent) 14%, transparent)}
.rs{will-change:transform}
.ri{height:64px; display:grid; align-content:center; justify-items:center; gap:3px; padding:0 12px; text-align:center}
.ri b{font:700 21px/1.1 var(--f-head); letter-spacing:.02em; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; max-width:100%}
.ri span{font:600 12px/1 var(--f-head); letter-spacing:.08em; text-transform:uppercase; color:var(--muted)}
.rres{min-height:1px; position:absolute; width:1px; overflow:hidden; clip:rect(0 0 0 0)}
.racts{display:grid; gap:8px; margin-top:14px}
/* the list import (New Recruit's JSON export): its row on the home screen, its sheet, and Remove on an imported list's Overview */
.imprt{margin-top:18px}
.impf{position:relative; display:flex; align-items:center; justify-content:center; width:100%; margin:2px 0 10px; cursor:pointer}
.impf:focus-within{outline:2px solid var(--accent); outline-offset:2px}
.impf input{position:absolute; inset:0; width:100%; height:100%; opacity:0; cursor:pointer}
.impt{display:block; width:100%; min-height:88px; resize:vertical; padding:9px 10px; border-radius:8px; border:1px solid var(--line); background:var(--bg); color:var(--fg); font:15px/1.35 var(--f-body)}
.impgo{display:block; width:100%; margin-top:10px}
.impno{margin-top:12px; padding:10px 12px 12px; border-radius:10px; box-shadow:inset 0 0 0 1px var(--line)}
.impno .qh{margin:0 0 6px; color:var(--dm-bad)}
.impno .lead{margin:4px 0 0}
.impl{margin:4px 0 0; padding-left:18px; font-size:14.5px; line-height:1.4; overflow-wrap:anywhere}
.impl li + li{margin-top:4px}
.imprm{margin-top:10px}
.imprm > .btn2{width:100%}
.imprm .lead{margin:0}
.btn{min-height:48px; padding:0 14px; text-align:center; border-radius:8px; background:var(--accent); color:var(--accent-ink); font:700 16px/1.1 var(--f-head); letter-spacing:.04em}
.btn2{min-height:44px; padding:0 14px; text-align:center; border-radius:8px; box-shadow:inset 0 0 0 1px var(--line); color:var(--fg); font:700 15px/1 var(--f-head); letter-spacing:.06em; text-transform:uppercase}
.btn:active, .btn2:active{opacity:.75}
/* a unit's Damaged band (.def.dmg) as the datasheet has always drawn it: the calculator v1's .dmg table styles reached it, and
   the datasheet is kept exactly as it was */
.dmg{display:grid; grid-template-columns:minmax(0,1fr) repeat(3, auto); gap:2px 12px; margin-top:8px; font:600 13px/1.3 var(--f-head); color:var(--fg2); font-variant-numeric:tabular-nums}
.dmg span:nth-child(4n+1){color:var(--fg); overflow:hidden; text-overflow:ellipsis; white-space:nowrap}
.dmg span:nth-child(4n+2), .dmg span:nth-child(4n+3), .dmg span:nth-child(4n){text-align:right}
.dmg span:nth-child(-n+4){font-size:11px; letter-spacing:.08em; text-transform:uppercase; color:var(--muted)}
/* damage calculator: the sentence, the answer (pinned), what changes it */
.dmsen{margin-top:8px}
.dml1{display:grid; grid-template-columns:44px minmax(0,1fr); align-items:center; column-gap:6px}
.dmwd{font:600 12px/1 var(--f-head); letter-spacing:.1em; text-transform:uppercase; color:var(--muted)}
.dmtok{display:flex; align-items:center; gap:8px; min-height:46px; padding:6px 0; border-bottom:1px solid var(--line); text-align:left; min-width:0}
.dmtok b{flex:1; min-width:0; font:700 21px/1.12 var(--f-head); letter-spacing:.01em; text-decoration:underline dotted; text-decoration-color:var(--accent); text-underline-offset:4px}
.dmtok.empty b{color:var(--accent); text-decoration:none}
.dmtok:active{background:var(--surface)}
.dmvb{padding:8px 0}
/* the top control: Shoot | Fight | Both, three large segments, the one on filled; a mode the unit has no weapons for says so in it */
.dmmode{display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); border-radius:10px; box-shadow:inset 0 0 0 1.5px var(--line); overflow:hidden}
.dmmode button{display:grid; align-content:center; justify-items:center; gap:2px; min-width:0; min-height:50px; padding:4px 4px; text-align:center; color:var(--fg2)}
.dmmode button > span{font:700 17px/1.05 var(--f-head); letter-spacing:.07em; text-transform:uppercase}
.dmmode button > small{max-width:100%; font:500 10.5px/1.15 var(--f-body); letter-spacing:0; color:var(--muted)}
.dmmode button + button{box-shadow:inset 1.5px 0 0 var(--line)}
.dmmode button.on{background:var(--accent); color:var(--accent-ink); box-shadow:none}
.dmmode button.on > small{color:var(--accent-ink); opacity:.85}
.dmmode button:active{background:var(--surface2)}
.dmmode button.on:active{background:var(--accent)}
.dmans{position:relative; margin:12px -6px 0; padding:9px 12px 10px; border-radius:10px; background:var(--surface); box-shadow:0 1px 0 var(--line), 0 8px 18px rgba(0,0,0,.28)}
/* pinned while the list scrolls: a compact copy of the card over the top of the list (the card itself stays in its place, so nothing
   below it moves and no gap opens when it shrinks) */
.dmpinw{position:sticky; top:var(--top); height:0; z-index:6}
.dmpin{position:absolute; top:0; left:-6px; right:-6px}
.dmpin > .dmans{margin:0}
.dmans.static{position:static}
.dmctx{display:none; margin:0 0 2px; font:600 12px/1.2 var(--f-head); letter-spacing:.04em; color:var(--muted); white-space:nowrap; overflow:hidden; text-overflow:ellipsis}
.dmans.stuck .dmctx{display:block}
.dmans.stuck .dmbig > b{font-size:32px}
.dmans.stuck{padding-top:6px; padding-bottom:6px}
.dmans.stuck .dmchips, .dmans.stuck .dmcardf{display:none}
.dmans.stuck .dmbig > span{font-size:15px}
/* the number and what it is of on one line; the words under them take the card's whole width, so a wider number never re-wraps them */
.dmbig{display:grid; grid-template-columns:auto minmax(0,1fr); align-items:baseline; column-gap:10px; width:100%; text-align:left}
.dmbig > span{display:contents}
.dmbig > b{font:700 46px/.95 var(--f-head); color:var(--accent); font-variant-numeric:tabular-nums}
.dmbig > b.chg{animation:dmflash .7s ease-out}
@keyframes dmflash{0%{color:var(--fg); transform:scale(1.06)} 100%{color:var(--accent); transform:none}}
.dmbig > span{min-width:0; font:700 17px/1.15 var(--f-head); letter-spacing:.02em}
.dmbig > span small{grid-column:1 / -1; display:block; margin-top:4px; font:400 12.5px/1.3 var(--f-body); letter-spacing:0; color:var(--muted)}
.dmparts{margin-top:4px; font:600 13px/1.35 var(--f-head); letter-spacing:.02em; color:var(--fg2); font-variant-numeric:tabular-nums}
.dmans.stuck .dmparts{display:none}
.dmmsg{font-size:14.5px; line-height:1.45; color:var(--fg2)}
.dmchips{display:flex; flex-wrap:wrap; align-items:center; gap:5px; margin-top:8px}
.dmchip{display:inline-flex; align-items:center; gap:4px; max-width:100%; min-height:28px; padding:3px 9px; border-radius:999px; background:var(--accent); color:var(--accent-ink);
  font:700 12px/1.15 var(--f-head); letter-spacing:.04em; text-align:left}
.dmchip i{font-style:normal; font-size:14px; opacity:.7; margin-right:-2px}
.dmchip.auto{background:none; color:var(--fg); box-shadow:inset 0 0 0 1.5px var(--accent)}
.dmchip.info, .dmchip.none{background:var(--surface2); color:var(--fg2)}
.dmchip.none{font-weight:600}
.dmnc, .dmreset{min-height:28px; padding:0 4px; font:700 12px/1 var(--f-head); letter-spacing:.06em; text-transform:uppercase; color:var(--accent)}
.dmreset{margin-left:auto; color:var(--muted)}
.dmcardf{display:flex; align-items:center; gap:14px; margin-top:6px}
.dmans.stuck .dmcardf{margin-top:3px}
.dmans.prov .dmbig > b{opacity:.55}
.dmchips.all{max-height:40vh; overflow-y:auto}
.dmmore{min-height:28px; padding:0 6px; font:700 12px/1 var(--f-head); letter-spacing:.06em; text-transform:uppercase; color:var(--accent)}
.dmchip.over{background:none; color:var(--fg); box-shadow:none; border:1.5px dashed var(--accent); padding:1.5px 7.5px}
.dmchip.carry{background:var(--surface2); color:var(--fg); box-shadow:inset 0 0 0 1.5px var(--accent)}
/* a row: its divider is the wrapper's, under its picks (they are inside the row, never on the line); its effect's column has a fixed
   width and height, its secondary line (a crown, the largest other measure, why it changes nothing) is one line that is always there,
   and "+N more" sits over that line's end: nothing in it moves when the effects come in */
.dmrw{position:relative; border-bottom:1px solid var(--line); --fxw:96px}
.dmrh{position:relative}
.dmrw.hasmore .slot{padding-right:76px}
.dmmx{position:absolute; right:0; bottom:2px; min-width:66px; min-height:30px; padding:0 2px 0 6px; font:700 11px/1 var(--f-head); letter-spacing:.06em; text-transform:uppercase; color:var(--accent); text-align:right}
.dmmxl{margin:0; padding:0 4px 9px 30px; font:600 10.5px/1.35 var(--f-head); letter-spacing:.05em; text-transform:uppercase; color:var(--fg2)}
.dmchip.quiet{background:none; color:var(--fg2); box-shadow:inset 0 0 0 1px var(--line)}
.dmlv.flash{animation:dmflash2 1.2s ease-out}
@keyframes dmflash2{0%{background:var(--surface2)} 100%{background:none}}
.dmchip.ovr{background:none; color:var(--accent); border:1.5px dashed var(--accent); padding:1.5px 7.5px}
.dmhd{display:flex; align-items:baseline; justify-content:space-between; gap:8px; margin:20px 0 2px; font:700 15.5px/1.1 var(--f-head); letter-spacing:.1em; text-transform:uppercase; color:var(--fg)}
.dmhd small{font:600 11px/1 var(--f-head); letter-spacing:.08em; color:var(--muted)}
.dmh3{display:flex; align-items:baseline; gap:8px; margin:16px 0 0; padding-bottom:5px; border-bottom:1px solid var(--line); font:700 12.5px/1.2 var(--f-head); letter-spacing:.1em; text-transform:uppercase; color:var(--fg2)}
.dmh3 small{font:500 12px/1.2 var(--f-body); letter-spacing:0; text-transform:none; color:var(--muted)}
.dmsec .dmh3{margin-top:14px}
.dmlv{display:grid; grid-template-columns:20px minmax(0,1fr) var(--fxw); align-items:start; gap:0 10px; width:100%; padding:9px 2px 7px; text-align:left}
.dmlv:active{background:var(--surface)}
.dmlv .ck{width:20px; height:20px; margin-top:1px; border-radius:5px; box-shadow:inset 0 0 0 1.5px var(--muted); display:grid; place-items:center}
.dmlv.on .ck{background:var(--accent); box-shadow:none}
.dmlv.part .ck{background:var(--surface2); box-shadow:inset 0 0 0 1.5px var(--accent)}
.dmlv.part .ck::after{content:''; width:10px; height:2.5px; border-radius:2px; background:var(--accent)}
.dmlv.on .ck::after{content:''; width:10px; height:5px; margin-top:-3px; border:solid var(--accent-ink); border-width:0 0 2.5px 2.5px; transform:rotate(-45deg)}
.dmlv.rad .ck{border-radius:50%}
.dmlv.rad.on .ck{background:none; box-shadow:inset 0 0 0 2px var(--accent)}
.dmlv.rad.on .ck::after{width:10px; height:10px; margin:0; border:0; border-radius:50%; background:var(--accent); transform:none}
.dmlv .lb{display:grid; gap:2px; min-width:0}
.dmlv .lb b{font:700 15.5px/1.2 var(--f-head); letter-spacing:.02em}
.dmlv .lb small{font-size:12.5px; line-height:1.35; color:var(--muted)}
.dmlv .lb small .warn{color:var(--fg2)}
.dmlv .why{display:flex; flex-wrap:wrap; gap:2px 6px; align-items:baseline; color:var(--fg2)}
.dmlv .why:empty{display:none}
.dmlv .why .nw2{color:var(--fg2); font-style:italic}
.dmlv .slot{display:block; height:16px; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; font-size:12px; line-height:16px; color:var(--fg2)}
.dmlv .slot > .best{margin:0 6px 0 0; vertical-align:1px}
.dmlv.quiet .slot{color:var(--muted)}
.dmlv .why .ovr{color:var(--accent); font-weight:600}
.dmlv.out.on .ck{background:none; box-shadow:none; border:1.5px dashed var(--accent)}
.dmlv.out.on .ck::after{border-color:var(--accent)}
.dmlv .lb small > .warn, .dmlv .lb small > .dmkw{display:block}
.dmwst{display:flex; flex-wrap:wrap; gap:0 14px; margin-top:2px}
.dmwst > span{display:grid; justify-items:start}
.dmwst i{font:600 10.5px/1.15 var(--f-head); font-style:normal; letter-spacing:.08em; text-transform:uppercase; color:var(--muted)}
.dmlv .dmwst b{font:700 16px/1.2 var(--f-head); letter-spacing:0; font-variant-numeric:tabular-nums; color:var(--fg)}
.dmkw{margin-top:3px}
.dmlv .lb b .x{font-size:12.5px; margin-left:6px}
.dmwho{margin-left:6px; font:600 11px/1 var(--f-head); letter-spacing:.06em; text-transform:uppercase; color:var(--muted)}
.sd{display:inline-block; padding:1px 4px 0; border-radius:4px; box-shadow:inset 0 0 0 1px var(--line); font:600 10.5px/1.3 var(--f-head); letter-spacing:.08em; text-transform:uppercase; color:var(--muted)}
/* the effect: its number and unit in the row's right-hand column (fixed: 2 lines of words at most); a pick's on its line */
.fxm{display:contents}
.dmlv > .ck{grid-row:1}
.dmlv > .lb{grid-column:2}
.dmlv > .fx{grid-column:3; grid-row:1; display:grid; justify-items:end; align-content:start; gap:2px; height:46px; overflow:hidden; padding-top:1px; text-align:right}
.fxv{font:700 19px/1 var(--f-head); font-variant-numeric:tabular-nums; color:var(--fg)}
.fxv.up{color:var(--accent)}
.fxv.good{color:var(--dm-good)}
.fxv.bad{color:var(--dm-bad)}
.fxv.z{color:var(--muted)}
.fxv.est{opacity:.55}
.fxv.wait{color:var(--muted); letter-spacing:.1em}
.fxv.now{font:700 11px/1.6 var(--f-head); letter-spacing:.08em; text-transform:uppercase; color:var(--muted)}
.dmlv .fx > small{max-width:100%; font:600 10.5px/1.1 var(--f-head); letter-spacing:.04em; text-transform:uppercase; color:var(--muted); display:-webkit-box; -webkit-box-orient:vertical; -webkit-line-clamp:2; overflow:hidden}
.fxv.upd, .dmlv .fx > small.upd, .slot .upd, .best.upd, small.pa.upd{opacity:.45}
.best{display:inline-block; margin-top:3px; padding:2px 5px 1px; border-radius:4px; background:var(--accent); color:var(--accent-ink); font:700 10px/1.1 var(--f-head); font-style:normal; letter-spacing:.06em; text-transform:uppercase; white-space:nowrap}
/* a row's picks, inside the row under its words: a grid, so a pick's width never depends on its number */
.dmprof{display:grid; grid-template-columns:repeat(auto-fill, minmax(118px, 1fr)); align-items:stretch; gap:6px; padding:2px 2px 10px 30px}
.dmpl{grid-column:1 / -1; font:600 10.5px/1.2 var(--f-head); letter-spacing:.1em; text-transform:uppercase; color:var(--muted)}
.dmpp{display:grid; justify-items:start; align-content:start; gap:1px; min-width:0; min-height:42px; padding:5px 10px; border-radius:8px; box-shadow:inset 0 0 0 1px var(--line); text-align:left}
.dmpp b{font:700 14px/1.1 var(--f-head); letter-spacing:.02em; overflow-wrap:anywhere}
.dmpp em{display:flex; align-items:center; gap:5px; max-width:100%; height:18px; font-style:normal; white-space:nowrap; overflow:hidden}
.dmpp em small.pa{overflow:hidden; text-overflow:ellipsis}
.dmpp em .fxv{font-size:14px}
.dmpp em .best{margin:0}
.dmpp.on{background:var(--surface2); box-shadow:inset 0 0 0 2px var(--accent)}
.dmpp.over{box-shadow:none; border:1.5px dashed var(--accent)}
.dmpp small{font-size:11px; line-height:1.2; color:var(--muted)}
/* a weapon's profiles: one to a row, each with its characteristics and keywords */
.dmprofs{grid-template-columns:1fr}
.dmprofs .dmpp{grid-template-columns:minmax(0, 1fr) auto; column-gap:8px; padding:6px 10px 7px}
.dmprofs .dmpp > em{grid-column:2; grid-row:1; justify-self:end}
.dmprofs .dmpp > .dmwst, .dmprofs .dmpp > .dmkw, .dmprofs .dmpp > small{grid-column:1 / -1}
.dmpp .dmwst{gap:0 12px}
.dmpp .dmwst i{font-size:9.5px}
.dmpp .dmwst b{font:700 14px/1.15 var(--f-head); letter-spacing:0; font-variant-numeric:tabular-nums; color:var(--fg)}
.dmpp .dmkw{margin-top:2px; font-size:10.5px; line-height:1.3}
.dmpp em small.pa{color:var(--fg2)}
.dmouts{padding:6px 2px 2px}
.dmout{margin:4px 0 0; padding:0; font-size:12px; line-height:1.4; color:var(--muted)}
.dmout b{font:600 12.5px/1.2 var(--f-head); letter-spacing:.02em; color:var(--fg2)}
.dmoutl{display:grid; grid-template-columns:minmax(0, 1fr); gap:6px; margin:4px 0 0}
.dmop{display:inline-flex; flex-wrap:wrap; align-items:baseline; gap:2px 6px; max-width:100%; min-height:36px; padding:6px 10px; border-radius:8px; box-shadow:inset 0 0 0 1px var(--line); text-align:left; font-size:12.5px; line-height:1.3; color:var(--muted)}
.dmop b{font:600 13.5px/1.2 var(--f-head); letter-spacing:.02em; color:var(--fg2)}
.dmop em{display:inline-flex; align-items:baseline; justify-content:flex-end; gap:4px; flex:0 0 92px; margin-left:auto; overflow:hidden; white-space:nowrap; font-style:normal}
.dmop .fxv{font-size:13.5px}
.dmop .fxv.z{font:600 11px/1.2 var(--f-head); letter-spacing:.05em; text-transform:uppercase}
.dmop em small{font:600 10px/1.1 var(--f-head); letter-spacing:.05em; text-transform:uppercase; color:var(--muted)}
.dmop:active{background:var(--surface)}
.dmop.on{box-shadow:inset 0 0 0 1.5px var(--accent)}
.dmop .ovr{font-style:normal; font-weight:600; color:var(--accent)}
.dmturnl{display:flex; align-items:baseline; gap:8px; margin:3px 2px 0; font-size:12.5px; line-height:1.35; color:var(--muted)}
.dmmeas{margin:2px 2px 0; font-size:12.5px; line-height:1.35; color:var(--muted)}
.dmnone{margin:6px 0 2px}
.dmfold{border-bottom:1px solid var(--line); margin-top:14px}
.dmfold > summary{display:flex; align-items:center; justify-content:space-between; gap:8px; min-height:40px; padding:4px 2px; border-top:1px solid var(--line); font:600 12.5px/1.2 var(--f-head); letter-spacing:.08em; text-transform:uppercase; color:var(--fg2)}
.dmfold + .dmfold{margin-top:0}
.dmfold + .dmfold > summary{border-top:0}
.dmfold[open] > summary .chev{transform:rotate(180deg)}
.dmfold > .note{margin:0 0 6px}
.dmncr{display:flex; flex-wrap:wrap; align-items:baseline; gap:2px 6px; padding:6px 2px; border-top:1px solid var(--line)}
.dmncr b{font:700 14.5px/1.2 var(--f-head); letter-spacing:.02em}
.dmncr small{flex-basis:100%; font-size:12.5px; line-height:1.35; color:var(--muted)}
.dmncr .dmbh{min-height:34px; font-size:11.5px}
.dmman{display:grid; gap:6px; padding:6px 0 10px}
.dmstep{display:flex; align-items:center; gap:6px}
.dmstep > span{flex:1; font:600 15px/1.2 var(--f-head); letter-spacing:.02em}
.dmstep > b{min-width:38px; text-align:center; font:700 16px var(--f-head)}
.dmstep button{min-height:34px; min-width:36px; padding:0 10px; border-radius:6px; box-shadow:inset 0 0 0 1px var(--line); font:700 13px/1 var(--f-head); letter-spacing:.04em; color:var(--fg2)}
.dmstep button.rr.on{background:var(--accent); color:var(--accent-ink); box-shadow:none}
/* the target, set by hand: a row of wheels (scroll-snap columns, the value in the middle row), then its two boxes */
.dmtg{margin-top:12px}
.dmtgh{margin:0 0 6px}
.dws{display:grid; grid-template-columns:repeat(6, minmax(0, 1fr)); gap:6px}
.dws.left{grid-template-columns:repeat(auto-fill, minmax(84px, 1fr)); padding:4px 0 12px}
.dw{display:grid; align-content:end; gap:4px; min-width:0}
.dwl{font:600 11px/1.15 var(--f-head); letter-spacing:.06em; text-transform:uppercase; color:var(--muted); text-align:center; overflow:hidden; text-overflow:ellipsis; white-space:nowrap}
.dws.left .dwl{white-space:normal; display:-webkit-box; -webkit-box-orient:vertical; -webkit-line-clamp:3; letter-spacing:.03em; text-transform:none; font-size:12px; line-height:1.2; color:var(--fg2)}
.dwb{position:relative; border-radius:10px; background:var(--surface)}
.dwb::after{content:''; position:absolute; left:3px; right:3px; top:36px; height:36px; border-radius:7px; box-shadow:inset 0 0 0 2px var(--accent); pointer-events:none}
.dwv{height:108px; overflow-y:scroll; overscroll-behavior:contain; scroll-snap-type:y mandatory; scrollbar-width:none; -webkit-overflow-scrolling:touch; touch-action:pan-y; border-radius:10px; outline:none;
